import unittest
import colors


class TestParseHexColor(unittest.TestCase):
    def test_valid_full_boundaries(self):
        self.assertEqual(colors.parse_hex_color("#000000"), (0, 0, 0))
        self.assertEqual(colors.parse_hex_color("#ffffff"), (255, 255, 255))

    def test_valid_full_values(self):
        self.assertEqual(colors.parse_hex_color("#123456"), (18, 52, 86))

    def test_valid_full_case_insensitive(self):
        self.assertEqual(colors.parse_hex_color("#FFFFFF"), (255, 255, 255))
        self.assertEqual(colors.parse_hex_color("#aAbBcC"), (170, 187, 204))

    def test_valid_shorthand_boundaries(self):
        self.assertEqual(colors.parse_hex_color("#000"), (0, 0, 0))
        self.assertEqual(colors.parse_hex_color("#fff"), (255, 255, 255))

    def test_valid_shorthand_doubling(self):
        self.assertEqual(colors.parse_hex_color("#f80"), (255, 136, 0))

    def test_valid_shorthand_case_insensitive(self):
        self.assertEqual(colors.parse_hex_color("#FFF"), (255, 255, 255))
        self.assertEqual(colors.parse_hex_color("#F80"), (255, 136, 0))
        self.assertEqual(colors.parse_hex_color("#aBc"), (170, 187, 204))

    def test_missing_leading_hash_raises_value_error(self):
        with self.assertRaises(ValueError):
            colors.parse_hex_color("ffffff")
        with self.assertRaises(ValueError):
            colors.parse_hex_color("f80")

    def test_whitespace_raises_value_error(self):
        invalid_inputs = [
            " #ffffff",
            "#ffffff ",
            " #fff",
            "#fff ",
            "#ff ffff",
            "# f80",
            "\t#ffffff",
            "#ffffff\n",
        ]
        for text in invalid_inputs:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    colors.parse_hex_color(text)

    def test_signs_raise_value_error(self):
        invalid_inputs = ["+#ffffff", "-#ffffff", "#+fffff", "#-fffff", "+#fff", "-#fff"]
        for text in invalid_inputs:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    colors.parse_hex_color(text)

    def test_separators_raise_value_error(self):
        invalid_inputs = ["#ff-ff-ff", "#ff,ff,ff", "#ff:ff:ff", "#ff.ff.ff", "#f-8-0"]
        for text in invalid_inputs:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    colors.parse_hex_color(text)

    def test_non_hex_characters_raise_value_error(self):
        invalid_inputs = ["#gggggg", "#zzzzzz", "#12345g", "#zzz", "#f8g", "#!@#"]
        for text in invalid_inputs:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    colors.parse_hex_color(text)

    def test_invalid_lengths_raise_value_error(self):
        invalid_inputs = ["", "#", "#f", "#ff", "#ffff", "#fffff", "#fffffff", "#ffffffff"]
        for text in invalid_inputs:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    colors.parse_hex_color(text)


